#!/usr/bin/env python3
import os
import subprocess
import sys
import shutil
import argparse
from pathlib import Path

# The CMake template remains the same.
CMAKE_TEMPLATE = """
# Generated by build_wasm.py. Do not edit manually.

cmake_minimum_required(VERSION 3.13)
project({project_name_upper}_WASM_Build CXX)

set(CMAKE_CXX_STANDARD 17)

#=============================================================================
# TARGET 1: The '{project_name_lower}' static library
#=============================================================================

set(COMPONENT_ROOT_DIR ${{CMAKE_CURRENT_SOURCE_DIR}}/../..)
get_filename_component(COMPONENT_ROOT_DIR_ABS ${{COMPONENT_ROOT_DIR}} ABSOLUTE)

set(IMPL_DIR ${{COMPONENT_ROOT_DIR_ABS}}/Implementations/Cpp)
message(STATUS "Found Implementation sources at: ${{IMPL_DIR}}")

set(INTERFACES_DIR ${{IMPL_DIR}}/Interfaces)
file(GLOB STUB_SRC "${{IMPL_DIR}}/Stub/*.cpp")
set({project_name_upper}_SRC
    ${{STUB_SRC}}
    "${{INTERFACES_DIR}}/{project_name_lower}_interfaceexception.cpp"
    "${{INTERFACES_DIR}}/{project_name_lower}_interfacewrapper.cpp"
)

add_library({project_name_lower} STATIC ${{{project_name_upper}_SRC}})

target_include_directories({project_name_lower} PUBLIC
    "${{IMPL_DIR}}/Stub"
    "${{INTERFACES_DIR}}"
)

#=============================================================================
# TARGET 2: The final WASM executable
#=============================================================================

message(STATUS "Using WASM binding file: ${{WASM_BINDING_FILE}}")
message(STATUS "Setting WASM output name to: ${{WASM_OUTPUT_NAME}}")

set(BINDINGS_DIR ${{COMPONENT_ROOT_DIR_ABS}}/Bindings)
add_executable(${{WASM_OUTPUT_NAME}} ${{WASM_BINDING_FILE}})

target_include_directories(${{WASM_OUTPUT_NAME}} PRIVATE
    "${{BINDINGS_DIR}}"
)

target_link_libraries(${{WASM_OUTPUT_NAME}} PRIVATE {project_name_lower})

target_link_options(${{WASM_OUTPUT_NAME}} PRIVATE
    "-s WASM=1"
    "-s MODULARIZE=1"
    "-s EXPORT_ES6=1"
    "-s EXPORT_ALL=1"
    "-s ALLOW_MEMORY_GROWTH=1"
    "-s MAXIMUM_MEMORY=4294967296"  # 4GB
    "-s INITIAL_MEMORY=1073741824"  # 1GB
    "-s FORCE_FILESYSTEM=1"
    "-s EXPORTED_RUNTIME_METHODS=['ccall','cwrap']"
    "--bind"
    "-s EXCEPTION_CATCHING_ALLOWED=['*']"
    "-s ASSERTIONS=1"
)

set_target_properties(${{WASM_OUTPUT_NAME}} PROPERTIES OUTPUT_NAME "${{WASM_OUTPUT_NAME}}")

message(STATUS "Unified build configuration for '{project_name_upper}' complete.")
"""

def run_command(command, working_directory):
    """Executes a command and provides detailed error reporting."""
    try:
        process = subprocess.run(
            command, cwd=working_directory, check=True, capture_output=True,
            text=True, encoding='utf-8'
        )
        if process.stdout:
            print(process.stdout)
        return True
    except FileNotFoundError:
        print(f"Error: Command '{command[0]}' not found. Is it in your PATH?", file=sys.stderr)
        return False
    except subprocess.CalledProcessError as e:
        print(f"Error: Command failed with exit code {e.returncode}.", file=sys.stderr)
        print(f"--- STDOUT ---\n{e.stdout}", file=sys.stderr)
        print(f"--- STDERR ---\n{e.stderr}", file=sys.stderr)
        return False

def main():
    """Derives project info, generates files, builds, and cleans up."""
    parser = argparse.ArgumentParser(description="Generates and builds a WASM binding for an ACT component.")
    parser.add_argument(
        "--no-cleanup",
        dest='cleanup',
        action='store_false',
        help="Do not remove build artifacts (build directory, CMakeLists.txt) after a successful build."
    )
    args = parser.parse_args()

    script_dir = Path(__file__).parent.resolve()
    build_dir = script_dir / "build"
    cmake_file_path = script_dir / "CMakeLists.txt"

    # --- Pre-build Cleanup ---
    print("[+] Performing pre-build cleanup...")
    if build_dir.exists():
        shutil.rmtree(build_dir)
        print(f"Removed old build directory: '{build_dir.name}'")
    if cmake_file_path.exists():
        cmake_file_path.unlink()
        print(f"Removed old file: '{cmake_file_path.name}'")
    for pattern in ["*Binding.js", "*Binding.wasm"]:
        for old_file in script_dir.glob(pattern):
            old_file.unlink()
            print(f"Removed old artifact: '{old_file.name}'")
    print("Pre-build cleanup complete.")

    # --- Derive Project Name ---
    component_root_dir = script_dir.parent.parent
    component_dir_name = component_root_dir.name
    if not component_dir_name.endswith("_component"):
        sys.exit(f"Fatal: Script is not in the expected directory structure: .../{{PROJECT_NAME}}_component/Examples/WASM")
    project_name = component_dir_name.replace("_component", "")
    project_name_lower = project_name.lower()
    print(f"Project name inferred: '{project_name}'")

    # --- Dynamically find the WASM binding file ---
    bindings_wasm_dir = component_root_dir / "Bindings" / "WASM"
    binding_files = list(bindings_wasm_dir.glob("*_bindings.cpp"))
    if not binding_files:
        sys.exit(f"Fatal: No '*_bindings.cpp' file found in {bindings_wasm_dir}")
    if len(binding_files) > 1:
        sys.exit(f"Fatal: Found multiple '*_bindings.cpp' files: {binding_files}")

    binding_file_path = binding_files[0]
    print(f"Found binding file: {binding_file_path.name}")
    
    # --- Determine output name ---
    output_name_base = binding_file_path.stem.replace("_bindings", "")
    wasm_output_name = f"{output_name_base}Binding"
    print(f"WASM output name set to: '{wasm_output_name}'")

    # --- Run Build Steps ---
    print(f"\n[1/4] Generating CMake file...")
    try:
        cmake_content = CMAKE_TEMPLATE.format(
            project_name_lower=project_name_lower,
            project_name_upper=project_name.upper()
        )
        with open(cmake_file_path, "w", encoding='utf-8') as f:
            f.write(cmake_content.strip())
    except IOError as e:
        sys.exit(f"Fatal: Could not write to file '{cmake_file_path}'. Reason: {e}")

    print(f"[2/4] Creating build directory: '{build_dir.name}'")
    build_dir.mkdir(exist_ok=True)

    print("[3/4] Configuring project with emcmake")
    configure_cmd = [
        "emcmake", "cmake", f"-DWASM_BINDING_FILE={binding_file_path}",
        f"-DWASM_OUTPUT_NAME={wasm_output_name}", "-S", str(script_dir),
        "-B", str(build_dir)
    ]
    if not run_command(configure_cmd, script_dir):
        sys.exit("CMake configuration failed.")

    print("[4/4] Building all targets with CMake")
    build_cmd = ["cmake", "--build", str(build_dir)]
    if not run_command(build_cmd, script_dir):
        sys.exit("Build failed.")

    print(f"\nBuild complete. Main output file: {build_dir / wasm_output_name}.js")

    # --- Post-build Cleanup ---
    if args.cleanup:
        print("\n[+] Performing post-build cleanup...")
        try:
            for extension in [".js", ".wasm"]:
                artifact_name = f"{wasm_output_name}{extension}"
                source_path = build_dir / artifact_name
                if source_path.exists():
                    shutil.move(str(source_path), str(script_dir))
                    print(f"Moved '{artifact_name}' to current directory.")
            
            shutil.rmtree(build_dir)
            print(f"Removed build directory: '{build_dir.name}'")

            cmake_file_path.unlink()
            print(f"Removed generated file: '{cmake_file_path.name}'")

            print("Cleanup complete.")
        except (IOError, OSError) as e:
            print(f"\nWarning: Post-build cleanup failed. Reason: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()